 protected override bool ReleaseHandle(){RepairInterop.Release(handle,kind);return true;}
 internal static RepairHandle Own(nint token,int kind){try{return new(token,kind);}catch{RepairInterop.Release(token,kind);throw;}}
 internal RepairHandle Live(object owner){ObjectDisposedException.ThrowIf(IsClosed,owner);return this;}
}
