public sealed unsafe class WireDataSnapshot : IDisposable {
 readonly RepairHandle handle;
 internal WireDataSnapshot(nint token)=>handle=RepairHandle.Own(token,0);
 internal RepairHandle NativeHandle=>handle.Live(this);
 int Info(int index){int* data=stackalloc int[4];RepairInterop.Check(RepairInterop.WireInfo(NativeHandle,data,4));return data[index];}
 /// <summary>Gets ordered edge count.</summary>
 public int Count=>Info(0);
 /// <summary>Gets separately stored nonmanifold edge count.</summary>
 public int NonManifoldCount=>Info(1);
 /// <summary>Gets the chosen native manifold policy.</summary>
 public bool ManifoldMode=>Info(2)!=0;
 /// <summary>Reports whether FromWire's original storage was already chained.</summary>
 public bool WasChained=>Info(3)!=0;
 /// <summary>Copies an edge set, including duplicates and orientation, into new sequence storage.</summary>
 public static WireDataSnapshot Create(OwnedShapeSet edges,bool manifold=true){ArgumentNullException.ThrowIfNull(edges);RepairInterop.Check(RepairInterop.WireCreate(edges.NativeHandle,manifold?1:0,out var p));return new(p);}
 /// <summary>Loads a wire with explicit chaining and manifold policies.</summary>
 public static WireDataSnapshot FromWire(Shape wire,bool alreadyChained=true,bool manifold=true){ArgumentNullException.ThrowIfNull(wire);RepairInterop.Check(RepairInterop.WireFrom(wire.Handle,alreadyChained?1:0,manifold?1:0,out var p));return new(p);}
 Shape Get(int selector,int index){RepairInterop.Check(RepairInterop.WireShape(NativeHandle,selector,index,out var p));return ShapeFactory.FromNativeHandle(p,"repair_wiredata_shape");}
 /// <summary>Returns an owning edge value at a one-based index.</summary>
 public Shape GetEdge(int index)=>Get(0,index);
 /// <summary>Returns an owning nonmanifold edge at a one-based index.</summary>
 public Shape GetNonManifoldEdge(int index)=>Get(1,index);
 /// <summary>Returns copied nonmanifold sequence storage.</summary>
 public OwnedShapeSet NonManifoldEdges {get{RepairInterop.Check(RepairInterop.WireNonManifold(NativeHandle,out var p));return new(p);}}
 /// <summary>Builds an owning wire using native Wire or WireAPIMake.</summary>
 public Shape ToWire(bool apiBuilder=false)=>Get(apiBuilder?3:2,0);
 /// <summary>Returns the native first matching index, or zero when absent.</summary>
 public int IndexOf(Shape edge){ArgumentNullException.ThrowIfNull(edge);RepairInterop.Check(RepairInterop.WireIndex(NativeHandle,edge.Handle,out var n));return n;}
 WireDataSnapshot Edit(Shape input,int operation,int index,int overload){ArgumentNullException.ThrowIfNull(input);RepairInterop.Check(RepairInterop.WireEdit(NativeHandle,input.Handle,operation,index,overload,out var p));return new(p);}
 /// <summary>Inserts an edge before a one-based index; zero appends.</summary>
 public WireDataSnapshot InsertEdge(Shape edge,int index=0)=>Edit(edge,0,index,0);
 /// <summary>Inserts a wire's edges; zero appends.</summary>
 public WireDataSnapshot InsertWire(Shape wire,int index=0)=>Edit(wire,0,index,1);
 /// <summary>Inserts either an edge or wire using the native Shape overload.</summary>
 public WireDataSnapshot InsertShape(Shape shape,int index=0)=>Edit(shape,0,index,2);
 /// <summary>Appends or prepends an edge, optionally reversed. Modes 0/1 append forward/reversed; 2/3 prepend forward/reversed.</summary>
 public WireDataSnapshot AddOrientedEdge(Shape edge,int mode)=>Edit(edge,1,mode,0);
 /// <summary>Adds an oriented wire with native mode 0..3.</summary>
 public WireDataSnapshot AddOrientedWire(Shape wire,int mode)=>Edit(wire,1,mode,1);
 /// <summary>Adds an edge or wire through the native Shape overload.</summary>
 public WireDataSnapshot AddOrientedShape(Shape shape,int mode)=>Edit(shape,1,mode,2);
 /// <summary>Returns a new snapshot with one replaced edge.</summary>
 public WireDataSnapshot SetEdge(int index,Shape edge)=>Edit(edge,2,index,0);
 /// <summary>Releases sequence storage; previously obtained shape values survive.</summary>
 public void Dispose()=>handle.Dispose();
}
/// <summary>Copied native patch-index bounds and their completeness check.</summary>
public readonly record struct RepairPatchBounds(int UMin,int UMax,int VMin,int VMax,bool IsComplete=false);
/// <summary>Private wire segment with detached sequence and patch storage. Calls serialize; native mutation failure retires the segment.</summary>
public sealed unsafe class RepairWireSegment : IDisposable {
 readonly RepairHandle handle;
 RepairHandle NativeHandle=>handle.Live(this);
 RepairWireSegment(nint p)=>handle=RepairHandle.Own(p,1);
 int Info(int index){int* p=stackalloc int[4];RepairInterop.Check(RepairInterop.SegmentInfo(NativeHandle,p,4));return p[index];}
 /// <summary>Constructs a private segment. Orientation follows TopAbs_Orientation's native 0..3 domain.</summary>
 public static RepairWireSegment Create(WireDataSnapshot wire,int orientation=3){ArgumentNullException.ThrowIfNull(wire);RepairInterop.Check(RepairInterop.SegmentCreate(wire.NativeHandle,orientation,out var p));return new(p);}
 /// <summary>Gets edge count.</summary>
 public int Count=>Info(0);
 /// <summary>Gets or sets the native traversal orientation.</summary>
 public int Orientation {get=>Info(1);set=>RepairInterop.Check(RepairInterop.SegmentConfigure(NativeHandle,0,2,value));}
 /// <summary>Reports a separately stored vertex.</summary>
 public bool IsVertex=>Info(2)!=0;
 /// <summary>Reports exact endpoint identity; empty segments return false.</summary>
 public bool IsClosed=>Info(3)!=0;
 /// <summary>Copies the complete wire sequence storage.</summary>
 public WireDataSnapshot WireData {get{RepairInterop.Check(RepairInterop.SegmentData(NativeHandle,out var p));return new(p);}}
 Shape Get(int selector,int index=0){RepairInterop.Check(RepairInterop.SegmentShape(NativeHandle,selector,index,out var p));return ShapeFactory.FromNativeHandle(p,"repair_segment_shape");}
 /// <summary>Returns an owning edge at a one-based index.</summary>
 public Shape GetEdge(int index)=>Get(0,index);
 /// <summary>Gets an owning first endpoint vertex.</summary>
 public Shape FirstVertex=>Get(1);
 /// <summary>Gets an owning last endpoint vertex.</summary>
 public Shape LastVertex=>Get(2);
 /// <summary>Gets the separately stored vertex; rejects an unset vertex.</summary>
 public Shape Vertex=>Get(3);
 /// <summary>Gets all four patch bounds together.</summary>
 public RepairPatchBounds GetPatch(int index){int* p=stackalloc int[5];RepairInterop.Check(RepairInterop.SegmentPatch(NativeHandle,index,p,5));return new(p[0],p[1],p[2],p[3],p[4]!=0);}
 /// <summary>Sets all patch bounds after range validation.</summary>
 public void SetPatch(int index,RepairPatchBounds p)=>Patch(index,0,p);
 void Patch(int index,int op,RepairPatchBounds p)=>RepairInterop.Check(RepairInterop.SegmentSetPatch(NativeHandle,index,op,p.UMin,p.UMax,p.VMin,p.VMax));
 /// <summary>Tightens one bound: 0 UMin, 1 UMax, 2 VMin, 3 VMax; inconsistent ranges are rejected before mutation.</summary>
 public void TightenPatch(int index,int bound,int value){if(bound<0 || bound>3)throw new ArgumentOutOfRangeException(nameof(bound));Patch(index,bound+1,bound switch{0=>new(value,32000,-32000,32000),1=>new(-32000,value,-32000,32000),2=>new(-32000,32000,value,32000),_=>new(-32000,32000,-32000,value)});}
 /// <summary>Replaces one edge while retaining its patch indices.</summary>
 public void SetEdge(int index,Shape edge){ArgumentNullException.ThrowIfNull(edge);RepairInterop.Check(RepairInterop.SegmentEdit(NativeHandle,edge.Handle,0,index,null,0));}
 /// <summary>Adds an edge with optional explicit patch bounds; zero appends.</summary>
 public void AddEdge(Shape edge,int index=0,RepairPatchBounds? patch=null){ArgumentNullException.ThrowIfNull(edge);int* values=stackalloc int[4];if(patch is{} p){values[0]=p.UMin;values[1]=p.UMax;values[2]=p.VMin;values[3]=p.VMax;}RepairInterop.Check(RepairInterop.SegmentEdit(NativeHandle,edge.Handle,patch.HasValue?2:1,index,values,patch.HasValue?4:0));}
 /// <summary>Sets the separately stored vertex.</summary>
 public void SetVertex(Shape vertex){ArgumentNullException.ThrowIfNull(vertex);RepairInterop.Check(RepairInterop.SegmentEdit(NativeHandle,vertex.Handle,3,0,null,0));}
 /// <summary>Clears edge, vertex and patch storage.</summary>
 public void Clear()=>RepairInterop.Check(RepairInterop.SegmentConfigure(NativeHandle,0,0,0));
 /// <summary>Loads independently copied WireData storage and resets patch bounds.</summary>
 public void Load(WireDataSnapshot wire){ArgumentNullException.ThrowIfNull(wire);RepairInterop.Check(RepairInterop.SegmentLoad(NativeHandle,wire.NativeHandle,1,0));}
 /// <summary>Releases the private segment.</summary>
 public void Dispose()=>handle.Dispose();
}
/// <summary>Owns coupled native maps plus detached geometry for inspection. Map indices are zero-based snapshot traversal positions, never durable topology IDs.</summary>
public sealed class RepairCoupledWorkspace : IDisposable {
 readonly RepairHandle handle;
 internal RepairHandle NativeHandle=>handle.Live(this);
 internal RepairCoupledWorkspace(nint p)=>handle=RepairHandle.Own(p,3);
 /// <summary>Gets the native workflow kind: small edges, face orientation, loops, free bounds, edge fix, edge split or face loop repair.</summary>
 public int Kind {get{RepairInterop.Check(RepairInterop.WorkspaceInfo(NativeHandle,out var n,out _));return n;}}
 /// <summary>Gets the native diagnostic or repair change flag.</summary>
 public bool Changed {get{RepairInterop.Check(RepairInterop.WorkspaceInfo(NativeHandle,out _,out var flag));return flag!=0;}}
 /// <summary>Gets the native selected split index or cut-line flag, specific to the selected operation.</summary>
 public int SelectedNativeIndex {get{RepairInterop.Check(RepairInterop.WorkspaceSelected(NativeHandle,out var n));return n;}}
 OwnedShapeSet Set(int selector,int index=0){RepairInterop.Check(RepairInterop.WorkspaceSet(NativeHandle,selector,index,out var p));return new(p);}
 /// <summary>Gets detached small-edge, loop-small-edge or split-closed-wire keys.</summary>
 public OwnedShapeSet PrimaryKeys=>Set(0);
 /// <summary>Gets detached multiple-edge, loop-seam-edge or split-open-wire keys.</summary>
 public OwnedShapeSet SecondaryKeys=>Set(1);
 /// <summary>Gets detached keys of the first nested map.</summary>
 public OwnedShapeSet FirstMapKeys=>Set(2);
 /// <summary>Gets detached keys of the second nested map.</summary>
 public OwnedShapeSet SecondMapKeys=>Set(3);
 /// <summary>Gets independently retained workflow shapes.</summary>
 public OwnedShapeSet Shapes=>Set(4);
 /// <summary>Gets ordered values for a first-map key at its snapshot index.</summary>
 public OwnedShapeSet FirstMapValues(int index)=>Set(5,index);
 /// <summary>Gets ordered values for a second-map key at its snapshot index.</summary>
 public OwnedShapeSet SecondMapValues(int index)=>Set(6,index);
 /// <summary>Releases maps and retained parent; previously obtained outputs survive.</summary>
 public void Dispose()=>handle.Dispose();
}
